#!/usr/bin/env node
/** Canonical documentation inventory.
 * The index is derived only from files that exist in docs/. This makes a
 * documented retirement explicit instead of keeping a stale list of deleted
 * files as a permanent CI failure.
 *
 * The generated file is English: repository prose is English, and the note
 * column carries one line per document, so Spanish notes made the
 * `check:no-spanish` per-file baseline grow by one line for every document
 * added to the repository. English notes make that baseline shrink on every
 * pass instead.
 *
 * The STATE vocabulary below deliberately stays `vivo`/`transitorio`/
 * `archivo`/`retirable`: it is a machine-readable contract shared with
 * `check-docs-retire.mjs`, `check-documented-doc-references.mjs` and
 * `doctor-legacy-schema-map.mjs`, and with the ADR/PENDIENTES prose naming it.
 * Each row carries exactly one of those tokens, and `check:no-spanish` only
 * counts a line once it holds three distinct Spanish words (or two plus an
 * accent), so the vocabulary costs nothing against the baseline.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { MANUAL_FILES } from "./landing-registry.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DOCS_DIR = path.join(ROOT, "docs");
const INDEX_PATH = path.join(DOCS_DIR, "docs-state-index.md");
const ALLOWED_STATES = new Set(["vivo", "transitorio", "archivo", "retirable"]);
/** Header of the generated inventory table. The English form is canonical;
 *  the Spanish one is still recognised so an index generated before this
 *  change keeps parsing (two branch tips coexist while this merges back to
 *  release/v1.0.0, and a stale anchor would otherwise read as an empty
 *  inventory rather than a legacy one). */
const TABLE_HEADER = "| Document | State | Note |";
const LEGACY_TABLE_HEADER = "| Documento | Estado | Nota |"; // i18n-allow — legacy anchor kept for pre-migration indexes
/** Endonym basenames of the localized manual family (from the landing
 * registry), so the generated index labels manuals — not stale `manual-usuario`
 * spellings — as the manual family is renamed per locale. */
const MANUAL_BASENAMES = new Set(Object.values(MANUAL_FILES));

function normalizeEol(text) {
  return text.replace(/\r\n?/g, "\n");
}

function docsFiles() {
  if (!fs.existsSync(DOCS_DIR)) return [];
  return fs.readdirSync(DOCS_DIR)
    .filter((name) => /\.(?:md|yaml)$/i.test(name))
    .sort((a, b) => a.localeCompare(b))
    .map((name) => `docs/${name}`);
}

export function parseStateIndex(text) {
  const rows = [];
  let inTable = false;
  for (const line of text.split("\n")) {
    const value = line.trim();
    if (value.startsWith(TABLE_HEADER) || value.startsWith(LEGACY_TABLE_HEADER)) {
      inTable = true;
      continue;
    }
    if (!inTable || value.startsWith("|---")) continue;
    if (!value.startsWith("|")) {
      inTable = false;
      continue;
    }
    const cells = value.split("|").slice(1, -1).map((cell) => cell.trim());
    if (cells.length >= 3) {
      rows.push({ file: cells[0].replace(/`/g, ""), state: cells[1], note: cells[2] });
    }
  }
  return rows;
}

function noteFor(file) {
  if (file === "docs/docs-state-index.md") return "Canonical inventory generated by scripts/doctor-docs-index.mjs.";
  if (file.endsWith("legacy-schema-version-map.md")) return "Schema compatibility map generated from src/db/schema.ts.";
  if (file.endsWith("openapi.yaml")) return "Versioned OpenAPI contract of the companion server.";
  if (/^docs\/ADR-/.test(file)) return "Architectural decision record.";
  if (MANUAL_BASENAMES.has(file.replace(/^docs\//, "").replace(/\.(?:md|yaml)$/i, ""))) return "Localized user manual.";
  if (file === "docs/PENDIENTES.md") return "Register of pending work and known debt.";
  return "Document present in the checkout; review its state before retiring it.";
}

export function generateCanonicalIndex() {
  const files = docsFiles();
  const rows = files.map((file) => ({
    file,
    state: file === "docs/PENDIENTES.md" ? "transitorio" : "vivo",
    note: noteFor(file),
  }));
  const table = rows.map((row) => `| \`${row.file}\` | ${row.state} | ${row.note} |`);
  return [
    "# Documentation inventory — BookmarkForge",
    "",
    "This index is generated from the documents present in the checkout. A deleted document stops appearing here; any retirement must be traced in `docs/PENDIENTES.md` or in an ADR.",
    "",
    "## States",
    "",
    "| State | Meaning |",
    "|---|---|",
    "| `vivo` | Active document, or one a project flow depends on. |",
    "| `transitorio` | Document awaiting consolidation. |",
    "| `archivo` | Historical evidence kept for the record. |",
    "| `retirable` | May be deleted only after passing `check:docs-retire`. |",
    "",
    "## Documents present",
    "",
    TABLE_HEADER,
    "|---|---|---|",
    ...table,
    "",
    "## Retirement policy",
    "",
    "Retired documents are not reintroduced automatically. Before deleting a present document, mark it `retirable`, document the reason and pass the references gate. Operationally critical documents — operations, security and compliance — are not retirable: they must be kept or replaced by an equivalent document.",
    "",
  ].join("\n");
}

function main() {
  const update = process.argv.includes("--update");
  // The open-core export re-curates docs/ and does not ship the canonical
  // state index (export-public-repo.mjs EXCLUDED_DIRS + PUBLIC_DOCS whitelist),
  // so the gate skips there explicitly instead of failing: the inventory is
  // enforced upstream, in this repository. A missing index WITHOUT the export
  // manifest is still a hard failure — that is a real regression.
  const isPublicExport =
    !fs.existsSync(INDEX_PATH) && fs.existsSync(path.join(ROOT, "manifest.json"));
  if (isPublicExport && !update) {
    console.log(
      "[check:docs-index] skip: public export re-curates docs/ and excludes the canonical state index; the inventory is enforced upstream.",
    );
    return;
  }
  if (!fs.existsSync(INDEX_PATH)) {
    if (!update) {
      console.error(`Missing ${INDEX_PATH}; run node scripts/doctor-docs-index.mjs --update`);
      process.exit(1);
    }
    fs.writeFileSync(INDEX_PATH, "# placeholder\n", "utf8");
  }
  const canonical = generateCanonicalIndex();
  const current = fs.readFileSync(INDEX_PATH, "utf8");
  if (update) {
    fs.writeFileSync(INDEX_PATH, canonical, "utf8");
    console.log(`docs index updated: ${docsFiles().length} files`);
    return;
  }
  if (normalizeEol(current) !== normalizeEol(canonical)) {
    console.error("docs/docs-state-index.md has drift; run node scripts/doctor-docs-index.mjs --update");
    process.exit(2);
  }
  const rows = parseStateIndex(current);
  const expected = new Set(docsFiles());
  for (const row of rows) {
    if (!ALLOWED_STATES.has(row.state) || !expected.has(row.file) || !fs.existsSync(path.resolve(ROOT, row.file))) {
      console.error(`Invalid or missing indexed document: ${row.file}`);
      process.exit(3);
    }
  }
  if (!rows.some((row) => row.file === "docs/legacy-schema-version-map.md")) {
    console.error("docs index must include docs/legacy-schema-version-map.md");
    process.exit(4);
  }
  if (rows.length !== expected.size) {
    console.error(`docs index coverage drift: ${rows.length} rows, ${expected.size} files`);
    process.exit(5);
  }
  if (rows.some((row) => row.state === "retirable")) {
    console.error("docs index contains retirable rows; retirement requires explicit review");
    process.exit(6);
  }
  console.log(`docs-state-index checks OK (${rows.length} documents)`);
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1].replace(/\\/g, "/")}`).href) main();
